<?php
namespace Engenharia\Models;
class Photos_model extends EngenhariaBaseModel { protected $table = 'eng_photos'; public function __construct(){ parent::__construct($this->table); } public function forLaudo(int $id){return $this->db->table($this->db->prefixTable($this->table))->where('laudo_id',$id)->where('deleted',0)->orderBy('sort','ASC')->get();} public function add(array $data):int{$data+=array('deleted'=>0,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s'));$this->db->table($this->db->prefixTable($this->table))->insert($data);return(int)$this->db->insertID();} public function remove(int $id):bool{return(bool)$this->db->table($this->db->prefixTable($this->table))->where('id',$id)->where('deleted',0)->update(array('deleted'=>1,'updated_at'=>date('Y-m-d H:i:s')));} }
